"""Compatibility registry models (Milestone 5, workstream F). Pure: no I/O.

Two documents:

* ``compat/sources.json`` (:class:`Sources`, curated): which integrations exist and where their
  evidence lives. It has **no level field**: a typed-in level is refused (``extra="forbid"``).
* ``compat/registry.json`` (:class:`Registry`, generated by ``python -m concord.compat.build``):
  one entry per integration with the level derived from the evidence by the rules in
  :mod:`concord.compat.rules`. Its JSON Schema (``compat/registry.schema.json``) is generated
  from these models.
"""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

REGISTRY_VERSION = "1.0"
SOURCES_VERSION = "1.0"

Level = Literal["software_implemented", "protocol_tested", "hardware_verified", "human_validated"]
LEVELS: tuple[Level, ...] = (
    "software_implemented",
    "protocol_tested",
    "hardware_verified",
    "human_validated",
)
EvidenceType = Literal["test", "certify_report", "benchmark", "doc"]
Kind = Literal["builtin_adapter", "source_plugin", "offline_dataset"]
Claim = Literal["independent_reference_comparison", "approved_human_protocol"]
CertifyLevel = Literal["adapter_implementation", "protocol_tested", "hardware_tested"]
Modality = Literal["eeg", "meg", "emg", "ecog", "seeg", "intracortical", "other"]

DATE = r"^\d{4}-\d{2}-\d{2}$"
REL_PATH = r"^[A-Za-z0-9_][A-Za-z0-9_.\-/]*$"  # relative; the builder refuses paths leaving it
ID = r"^[a-z0-9][a-z0-9_.\-]{0,63}$"


class _Strict(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


# --------------------------------------------------------------------- curated sources (input)


class RecordRef(_Strict):
    """Where an opt-in test's execution is recorded (a document that contains ``anchor``)."""

    path: str = Field(pattern=REL_PATH, max_length=256)
    anchor: str = Field(min_length=3, max_length=200)


class SourceEvidence(_Strict):
    """One evidence item as curated. Certify reports are read from docs/compatibility/."""

    type: Literal["test", "benchmark", "doc"]
    path: str = Field(pattern=REL_PATH, max_length=256)
    description: str = Field(min_length=3, max_length=400)
    date: str = Field(pattern=DATE, description="when the evidence was produced / last changed")
    anchor: str | None = Field(
        default=None, min_length=3, max_length=200, description="text the file must contain"
    )
    protocol_reference: str | None = Field(
        default=None,
        min_length=3,
        max_length=300,
        description="test only: the real protocol stack / official reference implementation",
    )
    runs_in_ci: bool | None = Field(default=None, description="test only")
    record: RecordRef | None = Field(
        default=None, description="test with runs_in_ci=false: the recorded execution"
    )
    dataset_manifest: str | None = Field(
        default=None,
        pattern=REL_PATH,
        max_length=256,
        description="test only: SHA-256-pinned dataset manifest of the real recordings it reads",
    )
    claim: Claim | None = Field(default=None, description="doc only; see rules R3 / R4")


class ReadOnly(_Strict):
    statement: str = Field(min_length=10, max_length=400)
    verified_by: list[str] = Field(default_factory=list, max_length=8)


class SourceBuiltin(_Strict):
    id: str = Field(pattern=ID, description="adapter name; must appear in the code")
    kind: Literal["builtin_adapter", "offline_dataset"]
    display_name: str = Field(min_length=3, max_length=120)
    code: str = Field(pattern=REL_PATH, max_length=256, description="adapter module or package")
    ecosystem: str | None = Field(default=None, max_length=64)
    protocol: str = Field(min_length=3, max_length=200)
    synthetic_only: bool = False
    modalities_declared: list[Modality] = Field(default_factory=list)
    modality_note: str | None = Field(default=None, max_length=300)
    requires_modules: list[str] = Field(
        default_factory=list, description="optional Python modules this adapter needs at runtime"
    )
    read_only: ReadOnly
    evidence: list[SourceEvidence] = Field(default_factory=list)
    not_tested: list[str] = Field(default_factory=list)
    limitations: list[str] = Field(default_factory=list)


class SourcePlugin(_Strict):
    """Curated additions for a source plugin; identity and levels come from its certify reports."""

    package: str = Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.\-]{0,127}$")
    display_name: str | None = Field(default=None, max_length=120)
    source_dir: str | None = Field(
        default=None,
        pattern=REL_PATH,
        max_length=256,
        description="the package in this repository (pyproject.toml + src/<module>)",
    )
    protocol: str = Field(min_length=3, max_length=200)
    read_only: ReadOnly
    evidence: list[SourceEvidence] = Field(default_factory=list)
    not_tested: list[str] = Field(default_factory=list)
    limitations: list[str] = Field(default_factory=list)


class Sources(_Strict):
    sources_version: Literal["1.0"]
    builtins: list[SourceBuiltin]
    plugins: list[SourcePlugin]


# --------------------------------------------------------------------- registry (generated)


class LevelDefinition(_Strict):
    id: Level
    number: int = Field(ge=1, le=4)
    name: str
    meaning: str


class CertifyInfo(_Strict):
    level: CertifyLevel | None = Field(description="highest certification level in the report")
    tool: str
    plugin: str
    plugin_version: str
    entry_point: str
    device_key: str | None
    data_source: str = Field(description="session origin and declared flags")
    counts: dict[str, int]
    protocol_reference: str | None
    attestation_accepted: bool | None
    tree_sha256: str
    source_matches: bool | None = Field(
        description="report's plugin files equal this checkout's; None: source not in this repo"
    )
    changed_files: list[str]


class Evidence(_Strict):
    type: EvidenceType
    path: str
    description: str
    date: str = Field(pattern=DATE)
    supports: Literal["software_implemented", "protocol_tested"] | None = Field(
        description="the level this item supports by the rules; None: context only"
    )
    counted: bool = Field(
        description="False: listed but excluded from the level derivation (see note)"
    )
    note: str | None = None
    protocol_reference: str | None = None
    runs_in_ci: bool | None = None
    record: str | None = None
    real_data: bool = False
    claim: Claim | None = None
    certify: CertifyInfo | None = None


class Entry(_Strict):
    id: str
    display_name: str
    kind: Kind
    ecosystem: str | None
    protocol: str
    package: str
    version: str = Field(description="version the evidence is for")
    adapter: str | None = Field(description="built-in adapter name")
    entry_point: str | None = Field(description="plugin entry point (concord.sources)")
    module: str | None = Field(description="Python module or package that implements it")
    in_checkout: bool = Field(description="the integration's code exists in this checkout")
    synthetic_only: bool
    modalities_declared: list[str]
    modality_note: str | None
    read_only: ReadOnly
    level: Level | None = Field(description="derived; None: no counted evidence")
    level_number: int | None
    real_data_replay: bool
    level_basis: list[str] = Field(description="how the level was derived, rule by rule")
    evidence: list[Evidence]
    not_tested: list[str]
    limitations: list[str]
    requires_modules: list[str]


class RegistrySources(_Strict):
    curated: str
    certify_reports: list[str]
    validation_levels: str


class Registry(_Strict):
    registry_version: Literal["1.0"]
    notice: str
    concord_version: str
    levels: list[LevelDefinition]
    rules: list[str]
    sources: RegistrySources
    summary: dict[str, int]
    entries: list[Entry]
